/// Sidecar → UI events. Fields this client does not use are ignored by serde.
#[derive(Clone, Debug, Deserialize, PartialEq)]
#[serde(tag = "type")]
pub enum Event {
    #[serde(rename = "hello")]
    Hello {
        protocol: u64,
        #[serde(default)]
        commands: Vec<SlashSpec>,
    },
    #[serde(rename = "session.state")]
    SessionState {
        workspace_name: String,
        model: String,
        mode: String,
        git: Option<GitInfo>,
        busy: bool,
        /// The id the session is saved under (absent from older sidecars).
        #[serde(default)]
        session: Option<String>,
        #[serde(default)]
        posture: Option<PostureInfo>,
    },
    #[serde(rename = "assistant.delta")]
    AssistantDelta { turn_id: String, text: String },
    /// What the running turn is doing; sent on each phase change, independent of model output.
    #[serde(rename = "activity")]
    Activity {
        phase: String,
        #[serde(default)]
        step: u64,
        #[serde(default)]
        segment: u64,
        #[serde(default)]
        tool: Option<String>,
        #[serde(default)]
        subject: Option<String>,
        /// The turn's budget: total steps across segments, and the time limit in minutes.
        #[serde(default)]
        max_steps: Option<u64>,
        #[serde(default)]
        max_minutes: Option<u64>,
    },
    /// A file-edit tool changed a file: that operation's own diff, as a bounded preview.
            parse_event(r#"{"v":1,"type":"hello","protocol":1,"pid":42}"#),
            Ok(Event::Hello {
                protocol: 1,
                commands: Vec::new()
            })
        );
        assert_eq!(
            parse_event(
                r#"{"v":1,"type":"session.state","workspace":"/w/app","workspace_name":"app","model":"m","mode":"auto","git":{"branch":"main","dirty":2},"busy":false}"#
            ),
            Ok(Event::SessionState {
                workspace_name: "app".into(),
                model: "m".into(),
                mode: "auto".into(),
                git: Some(GitInfo {
                    branch: "main".into(),
                    dirty: 2
                }),
                busy: false,
                session: None,
                posture: None,
            })
        );
        assert_eq!(
            parse_event(
                r#"{"v":1,"type":"session.state","workspace":"/w/app","workspace_name":"app","model":"m","mode":"review","git":null,"busy":false,"posture":{"mode":"review","sandbox":"off","trusted":false}}"#
            ),
            Ok(Event::SessionState {
                workspace_name: "app".into(),
                model: "m".into(),
                mode: "review".into(),
                git: None,
                busy: false,
                session: None,
                posture: Some(PostureInfo {
                    mode: "review".into(),
                    sandbox: "off".into(),
                    trusted: false,
                }),
            })
        );
        assert!(matches!(
            parse_event(
                r#"{"v":1,"type":"session.state","workspace":"/w","workspace_name":"w","model":"m","mode":"review","git":null,"busy":true}"#
            ),
            Ok(Event::SessionState {
                git: None,
                busy: true,
                ..
            })
        ));
        assert_eq!(
            parse_event(r#"{"v":1,"type":"assistant.delta","turn_id":"t1","text":"hi"}"#),
            Ok(Event::AssistantDelta {
                turn_id: "t1".into(),
                text: "hi".into()
            })
        );
        assert_eq!(
            parse_event(
                r#"{"v":1,"type":"tool.start","turn_id":"t1","call_id":"c1","tool":"read_file","subject":"src/a.ts"}"#
        if matches!(self.link, Link::Crashed { .. }) {
            return;
        }
        match event {
            Event::Hello { protocol, commands } if protocol == PROTOCOL_VERSION => {
                self.commands = commands;
                self.link = Link::Ready;
            }
            Event::Hello { protocol, .. } => self.fail(
                format!("The agent sidecar speaks protocol {protocol}; this view needs protocol {PROTOCOL_VERSION}."),
                None,
                Vec::new(),
            ),
            Event::SessionState { workspace_name, model, mode, git, busy, session, posture } => {
                self.session = Session {
                    session_id: session,
                    workspace_name,
                    model,
                    mode,
                    branch: git.as_ref().map(|git| git.branch.clone()),
                    dirty: git.map_or(0, |git| git.dirty),
                    busy,
                    posture,
                };
                self.cancel_requested &= busy;
                if !self.cancel_requested {
                    self.cancel_started = None;
                }
                self.link = Link::Ready;
                if busy && self.turn_started.is_none() {
                    self.turn_started = Some(Instant::now());
                }
                if !busy {
                    self.turn_started = None;
                    self.activity = None;
                }
            }
            Event::Activity { phase, step, segment, tool, subject, max_steps, max_minutes } => {
                if self.activity.as_ref().is_none_or(|previous| previous.step != step) {
                    self.assistant_break = true;
                }
                let since = match &self.activity {
                    Some(previous) if previous.phase == phase && previous.tool == tool => previous.since,
                    _ => Instant::now(),
                };
                self.activity = Some(Activity { phase, step, segment, tool, subject, since, max_steps, max_minutes });
            }
            Event::FileDiff {
                call_id,
                evidence,
                path,
                kind,
                added,
                removed,
                preview,
                truncated,
                total_lines,
                diff_lines,
                hunks,
                full_path,
                note,
64:    (server as any).emitSessionState();

